  const bySession = new Map()
  for (const e of lines) {
    const s = bySession.get(e.sessionId) ?? { n: 0, agents: new Set(), kinds: new Map(), first: e.seq, firstTs: e.ts }
    s.n++
    s.agents.add(e.agentId)
    s.kinds.set(e.kind, (s.kinds.get(e.kind) ?? 0) + 1)
    bySession.set(e.sessionId, s)
  }
  const ts = lines.map(e => Date.parse(e.ts))
  console.log(`=== ${name} (${lines.length} events, span ${((Math.max(...ts) - Math.min(...ts)) / 1000).toFixed(0)}s) ===`)
  for (const [k, v] of bySession) {
    console.log(JSON.stringify({ session: k, n: v.n, first: v.first, agents: [...v.agents], kinds: Object.fromEntries(v.kinds) }))
