import { readFileSync } from 'node:fs'

const file = process.argv[2]
const lines = readFileSync(file, 'utf8').trim().split('\n').map(l => JSON.parse(l))
const seqs = lines.map(e => e.seq)
const unique = new Set(seqs)
console.log('events', lines.length, 'unique seq', unique.size, 'min', Math.min(...seqs), 'max', Math.max(...seqs))
let monotonic = true
for (let i = 1; i < seqs.length; i++) if (seqs[i] <= seqs[i - 1]) { monotonic = false; break }
console.log('seq monotonic in file order:', monotonic)
const tsv = lines.map(e => e.ts)
console.log('ts typeof', typeof tsv[0], 'first', tsv[0], 'last', tsv[tsv.length - 1])
let tsMono = true
for (let i = 1; i < tsv.length; i++) if (tsv[i] < tsv[i - 1]) { tsMono = false; break }
console.log('ts monotonic in file order:', tsMono)
const span = (Math.max(...tsv) - Math.min(...tsv)) / 1000
console.log('span seconds', span.toFixed(0))
// order of first appearance per session
const seen = []
const set = new Set()
for (const e of lines) if (!set.has(e.sessionId)) { set.add(e.sessionId); seen.push([e.sessionId, e.seq, e.ts]) }
console.log('session first-appearance order:')
for (const s of seen) console.log(' ', s[0], 'seq', s[1], 'ts', s[2])

