while (Date.now() - started < 12_000) {
  const { value, done } = await Promise.race([
    reader.read(),
    new Promise(resolve => setTimeout(() => resolve({ value: undefined, done: true }), 3_000)),
  ])
  if (done) break
  buffer += decoder.decode(value, { stream: true })
  const parts = buffer.split('\n\n')
  buffer = parts.pop() ?? ''
  for (const part of parts) {
    const line = part.split('\n').find(l => l.startsWith('data: '))
    if (line === undefined) continue
    events.push(JSON.parse(line.slice(6)))
  }
}
await reader.cancel()
const seqs = events.map(e => e.seq)
console.log('frames', events.length, 'unique seq', new Set(seqs).size, 'min', Math.min(...seqs), 'max', Math.max(...seqs))
let mono = true
for (let i = 1; i < seqs.length; i++) if (seqs[i] <= seqs[i - 1]) { mono = false; break }
console.log('seq monotonic in delivery order:', mono)
console.log('sample frame:', JSON.stringify(events[0]))
console.log('ts typeof:', typeof events[0]?.ts)
const bySession = new Map()
const kinds = new Map()
for (const e of events) {
  bySession.set(e.sessionId, (bySession.get(e.sessionId) ?? 0) + 1)
  kinds.set(e.kind, (kinds.get(e.kind) ?? 0) + 1)
}
console.log('sessions:')
for (const [k, v] of bySession) console.log('  ', k, v)
console.log('kinds:', Object.fromEntries(kinds))
const tsv = events.map(e => (typeof e.ts === 'number' ? e.ts : Date.parse(e.ts)))
console.log('ts span s', ((Math.max(...tsv) - Math.min(...tsv)) / 1000).toFixed(0))
let tsMono = true
for (let i = 1; i < tsv.length; i++) if (tsv[i] < tsv[i - 1]) { tsMono = false; break }
console.log('ts monotonic in delivery order:', tsMono)
// agentId per session
const agents = new Map()
for (const e of events) {
  const set = agents.get(e.sessionId) ?? new Set()
  set.add(e.agentId)
  agents.set(e.sessionId, set)
}
for (const [k, v] of agents) console.log('  agents', k.slice(-18), [...v].join(','))

