/*
 * Labels and readouts drawn over the workflow graph.
 *
 * The node names ride in the scene through drei's `Html`, so they stay crisp
 * at any camera distance; the hover card is the only one that takes pointer
 * events, and it is placed by the same projection as the name it replaces.
 * `--tone` carries the node's own colour in from the scene.
 */

.name {
  display: flex;
  align-items: center;
  gap: 7px;
  white-space: nowrap;
  pointer-events: none;
  font-size: 10.5px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: #8296b8;
  text-shadow: 0 0 10px rgba(4, 6, 11, 0.95);
  opacity: 0.66;
  transition: opacity 180ms ease, color 180ms ease;
}

.name[data-lit='true'] {
  color: #eef4ff;
  opacity: 1;
}

.name[data-idle='true'] { opacity: 0.32; }

.nameDot {
  width: 7px;
  height: 7px;
  flex: none;
  border-radius: 2px;
  background: var(--tone);
}

.name[data-lit='true'] .nameDot { box-shadow: 0 0 14px 1px var(--tone); }

.nameCount {
  font-family: var(--font-mono);
  font-size: 9.5px;
  letter-spacing: 0.06em;
  color: #5f708f;
}

.name[data-lit='true'] .nameCount { color: var(--tone); }

.card {
  pointer-events: none;
  min-width: 220px;
  max-width: 320px;
  padding: 9px 11px;
  border: 1px solid var(--line-strong);
  border-left: 2px solid var(--tone);
  border-radius: 8px;
  background: rgba(6, 10, 18, 0.94);
  box-shadow: 0 10px 34px rgba(0, 0, 0, 0.55);
}

.cardName {
  font-size: 12px;
  font-weight: 550;
  color: var(--ink);
  letter-spacing: -0.01em;
}

.cardId {
  margin-top: 3px;
  font-family: var(--font-mono);
  font-size: 9.5px;
  color: var(--ink-3);
  overflow-wrap: anywhere;
}

.cardFacts {
  margin-top: 6px;
  font-size: 10.5px;
  color: var(--ink-2);
  line-height: 1.5;
}

/* ------------------------------------------------------------- playback -- */

.playback {
  display: flex;
  align-items: center;
  gap: 8px;
  flex-wrap: wrap;
}

.speeds {
  display: flex;
  gap: 2px;
  margin-left: auto;
}

.speeds button {
  appearance: none;
  border: 1px solid var(--line);
  background: transparent;
  color: var(--ink-3);
  font-family: var(--font-mono);
  font-size: 10px;
  padding: 4px 7px;
  border-radius: 6px;
  cursor: pointer;
}

.speeds button[data-active='true'] {
  color: #d8f6ff;
  border-color: rgba(79, 216, 255, 0.45);
  background: rgba(79, 216, 255, 0.14);
}

.elapsed {
  width: 100%;
  margin: 0;
  font-size: 11px;
  color: var(--ink-3);
  font-family: var(--font-mono);
}

.elapsed b { color: var(--ink-2); font-weight: 500; }

/* ----------------------------------------------------------------- panel -- */

.sessions {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.session {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 100%;
  appearance: none;
  text-align: left;
  border: 1px solid transparent;
  border-radius: 7px;
  background: transparent;
  color: var(--ink-2);
  font-family: inherit;
  font-size: 11.5px;
  padding: 6px 8px;
  cursor: pointer;
}

.session:hover { background: rgba(122, 152, 205, 0.06); }
.session[data-selected='true'] { border-color: rgba(79, 216, 255, 0.35); background: rgba(79, 216, 255, 0.1); }

.sessionDot {
  width: 9px;
  height: 9px;
  flex: none;
  border-radius: 3px;
  background: var(--tone);
}

.sessionCount {
  margin-left: auto;
  font-family: var(--font-mono);
  font-size: 10px;
  color: var(--ink-3);
}

.seal {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.12em;
  color: var(--green);
}

.seal[data-tone='refused'] { color: var(--red); }

