  `--remote-debugging-port=${PORT}`,
  'about:blank',
], { stdio: ['ignore', 'pipe', 'pipe'] })
chrome.stderr.on('data', () => {})

async function page() {
  for (let attempt = 0; attempt < 60; attempt++) {
    try {
      const res = await fetch(`http://127.0.0.1:${PORT}/json/list`)
      const list = await res.json()
      const found = list.find(t => t.type === 'page')
      if (found) return found
    } catch {}
    await sleep(400)
  }
  throw new Error('devtools never came up')
}

const target = await page()
const ws = new WebSocket(target.webSocketDebuggerUrl)
await new Promise((resolve, reject) => {
  ws.addEventListener('open', resolve, { once: true })
  ws.addEventListener('error', reject, { once: true })
})

let nextId = 0
const pending = new Map()
const logs = []
ws.addEventListener('message', (message) => {
  const payload = JSON.parse(message.data)
  if (payload.id !== undefined) {
    pending.get(payload.id)?.(payload.result ?? payload.error)
    pending.delete(payload.id)
    return
  }
  if (payload.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(payload.params.type)) {
    logs.push(`${payload.params.type}: ${payload.params.args.map(a => a.value ?? a.description ?? '').join(' ')}`)
  }
  if (payload.method === 'Runtime.exceptionThrown') {
    logs.push(`exception: ${payload.params.exceptionDetails.exception?.description ?? payload.params.exceptionDetails.text}`)
  }
})
const send = (method, params = {}) => new Promise((resolve) => {
  const id = ++nextId
  pending.set(id, resolve)
  ws.send(JSON.stringify({ id, method, params }))
})

await send('Page.enable')
await send('Runtime.enable')
await send('Log.enable')
await send('Emulation.setDeviceMetricsOverride', { width: 1600, height: 1000, deviceScaleFactor: 1, mobile: false })
await send('Page.navigate', { url })
await sleep(settle)

if (script !== undefined) {
  const ran = await send('Runtime.evaluate', { expression: script, awaitPromise: true, returnByValue: true })
  console.log('script ->', JSON.stringify(ran?.result?.value ?? ran?.exceptionDetails ?? ran).slice(0, 4000))
  await sleep(2500)
}

const text = await send('Runtime.evaluate', {
  expression: 'JSON.stringify({ panel: document.querySelector(".panel")?.innerText?.slice(0,900) ?? null, hint: document.querySelector(".hint")?.innerText ?? null, canvas: !!document.querySelector("canvas") })',
  returnByValue: true,
})
console.log('page ->', text?.result?.value ?? 'no value')
console.log('logs ->', logs.slice(0, 12).join('\n         ') || 'none')
ws.close()
chrome.kill('SIGKILL')
process.exit(0)

