const res = await fetch('http://localhost:4711/runs/NodeGoat-2026-09-19T20-49-35/events')
const reader = res.body.getReader()
const decoder = new TextDecoder()
let buffer = ''
const events = []
const started = Date.now()
while (Date.now() - started < 12_000) {
  const { value, done } = await Promise.race([
    reader.read(),
    new Promise(r => setTimeout(() => r({ value: undefined, done: true }), 3_000)),
  ])
  if (done) break
  buffer += decoder.decode(value, { stream: true })
  const parts = buffer.split('\n\n')
  buffer = parts.pop() ?? ''
  for (const part of parts) {
    const line = part.split('\n').find(l => l.startsWith('data: '))
    if (line !== undefined) events.push(JSON.parse(line.slice(6)))
  }
}
await reader.cancel()
const seen = new Set()
const kept = events.filter(e => (seen.has(e.seq) ? false : (seen.add(e.seq), true)))
const t0 = Math.min(...kept.map(e => e.ts))
const by = new Map()
for (const e of kept) {
  const s = by.get(e.sessionId) ?? { n: 0, min: Infinity, max: -Infinity, cert: undefined }
  s.n++
  s.min = Math.min(s.min, e.ts)
  s.max = Math.max(s.max, e.ts)
  if (e.kind === 'certificate') s.cert = e.ts
  by.set(e.sessionId, s)
}
const mmss = ms => `${Math.floor(ms / 60000)}:${String(Math.floor((ms % 60000) / 1000)).padStart(2, '0')}`
for (const [k, v] of by) {
  console.log(k.slice(-22).padEnd(24), 'n', String(v.n).padStart(4),
    'from', mmss(v.min - t0), 'to', mmss(v.max - t0),
    'cert', v.cert === undefined ? '—' : mmss(v.cert - t0))
}
const cut = t0 + 501_000
console.log('at 8:21 admitted', kept.filter(e => e.ts <= cut).length, 'of', kept.length)

