  const events = raw.filter(e => (seen.has(e.seq) ? false : (seen.add(e.seq), true)))
  const graph = layoutWorkflow(events, agents)
  console.log(`\n=== ${name}: ${events.length} events -> ${graph.nodes.length} nodes, ${graph.edges.length} edges, dense=${graph.dense} ===`)
  for (const node of graph.nodes.slice(0, 12)) {
    console.log(
      `  tier ${node.tier} y ${node.y.toFixed(0).padStart(5)} ${node.label.padEnd(30)}`,
      `events ${String(node.events).padStart(4)} cert ${node.certificates} merge ${node.merges}`,
      node.integration ? 'INTEGRATION' : '', node.implied ? 'IMPLIED' : '',
    )
  }
  for (const edge of graph.edges.slice(0, 12)) {
    console.log(`  edge ${edge.kind} ${edge.from.slice(-14)} -> ${edge.to.slice(-14)}`)
  }
  console.log('  extent', graph.extent)
}

